(function bootstrapOpeningHours() {
  if (typeof window.opening_hours === 'function') return;
  var xhr = new XMLHttpRequest();
  xhr.open('GET', 'https://cdn.jsdelivr.net/npm/opening_hours@3.6.0/opening_hours.min.js', false);
  try {
    xhr.send(null);
    if (xhr.status >= 200 && xhr.status < 400 && xhr.responseText) {
      (0, eval)(xhr.responseText);
    }
  } catch (_) {}
})();
